        "content": "/** Result of YAML parsing. */\nexport interface ParseResult {\n  valid: boolean;\n  error?: {\n    message: string;\n    line: number;\n  };\n}\n\n/**\n * Strip inline comments from a line, respecting quoted strings.\n * An inline comment is ` #` (space followed by hash) that appears\n * outside of single or double quoted strings.\n */\nfunction stripInlineComment(line: string): string {\n  let inSingleQuote = false;\n  let inDoubleQuote = false;\n\n  for (let i = 0; i < line.length; i++) {\n    const ch = line[i];\n\n    if (ch === \"'\" && !inDoubleQuote) {\n      inSingleQuote = !inSingleQuote;\n    } else if (ch === '\"' && !inSingleQuote) {\n      inDoubleQuote = !inDoubleQuote;\n    } else if (ch === \"#\" && !inSingleQuote && !inDoubleQuote && i > 0 && line[i - 1] === \" \") {\n      return line.substring(0, i - 1);\n    }\n  }\n\n  return line;\n}\n\n/**\n * Check whether the trimmed content of a line (after indent removal)\n * represents a valid YAML line in the supported subset.\n *\n * Supported line types:\n * - List item: starts with `- ` or is exactly `-`\n * - Key-value pair: contains `: ` or ends with `:`\n */\nfunction isValidLineContent(content: string): boolean {\n  if (content === \"-\" || content.startsWith(\"- \")) {\n    return true;\n  }\n\n  if (content.endsWith(\":\")) {\n    const key = content.slice(0, -1);\n    return key.length > 0 && key.trimStart().length > 0;\n  }\n\n  const colonSpaceIndex = content.indexOf(\": \");\n  if (colonSpaceIndex > 0) {\n    const key = content.substring(0, colonSpaceIndex);\n    return key.length > 0 && key.trimStart().length > 0;\n  }\n\n  return false;\n}\n\n/** Parse YAML content and validate syntax for the supported subset. */\nexport function parseYaml(content: string): ParseResult {\n  if (content.length === 0 || content.trim().length === 0) {\n    return { valid: true };\n  }\n\n  const lines = content.split(\"\\n\");\n  const indentStack: number[] = [0];\n\n  for (let i = 0; i < lines.length; i++) {\n    const raw = lines[i];\n    const lineNum = i + 1;\n\n    if (raw.trim().length === 0) {\n      continue;\n    }\n\n    if (raw.trimStart().startsWith(\"#\")) {\n      continue;\n    }\n\n    const leadingWhitespace = raw.match(/^(\\s*)/)?.[1] ?? \"\";\n    if (leadingWhitespace.includes(\"\\t\")) {\n      return {\n        valid: false,\n        error: {\n          message: \"Tab characters are not allowed for indentation\",\n          line: lineNum,\n        },\n      };\n    }\n\n    const indent = leadingWhitespace.length;\n    const currentLevel = indentStack[indentStack.length - 1];\n\n    if (indent === currentLevel) {\n      // Same block, valid\n    } else if (indent > currentLevel) {\n      indentStack.push(indent);\n    } else {\n      while (indentStack.length > 1 && indentStack[indentStack.length - 1] > indent) {\n        indentStack.pop();\n      }\n      if (indentStack[indentStack.length - 1] !== indent) {\n        return {\n          valid: false,\n          error: {\n            message: \"Inconsistent indentation\",\n            line: lineNum,\n          },\n        };\n      }\n    }\n\n    const contentPart = raw.substring(indent);\n    const stripped = stripInlineComment(contentPart).trimEnd();\n\n    if (!isValidLineContent(stripped)) {\n      return {\n        valid: false,\n        error: {\n          message: \"Invalid syntax: expected key-value pair or list item\",\n          line: lineNum,\n        },\n      };\n    }\n  }\n\n  return { valid: true };\n}\n"
