import { parseYaml } from "./yaml-parser";

describe("parseYaml", () => {
  describe("valid cases", () => {
    test("empty file", () => {
      const result = parseYaml("");
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("whitespace-only file", () => {
      const result = parseYaml("  \n  \n");
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("comment-only file", () => {
      const result = parseYaml("# comment\n# another");
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("simple key-value", () => {
      const result = parseYaml("name: John");
      expect(result.valid).toBe(true);
    });

    test("multiple key-values", () => {
      const result = parseYaml("name: John\nage: 30");
      expect(result.valid).toBe(true);
    });

    test("simple list", () => {
      const result = parseYaml("- item1\n- item2");
      expect(result.valid).toBe(true);
    });

    test("nested mapping", () => {
      const result = parseYaml("parent:\n  child: value");
      expect(result.valid).toBe(true);
    });

    test("nested list under key", () => {
      const result = parseYaml("items:\n  - one\n  - two");
      expect(result.valid).toBe(true);
    });

    test("deep nesting", () => {
      const result = parseYaml("a:\n  b:\n    c: d");
      expect(result.valid).toBe(true);
    });

    test("inline comments", () => {
      const result = parseYaml("key: value # comment");
      expect(result.valid).toBe(true);
    });

    test("boolean values", () => {
      const result = parseYaml("flag: true");
      expect(result.valid).toBe(true);
    });

    test("null value", () => {
      const result = parseYaml("key: null");
      expect(result.valid).toBe(true);
    });

    test("key with colon in value", () => {
      const result = parseYaml("url: http://example.com");
      expect(result.valid).toBe(true);
    });

    test("quoted string value with double quotes", () => {
      const result = parseYaml('name: "John Doe"');
      expect(result.valid).toBe(true);
    });

    test("quoted string value with single quotes", () => {
      const result = parseYaml("name: 'John Doe'");
      expect(result.valid).toBe(true);
    });

    test("key with empty value (trailing colon)", () => {
      const result = parseYaml("key:");
      expect(result.valid).toBe(true);
    });

    test("dedent to previous valid level", () => {
      const result = parseYaml("a:\n  b: 1\nc: 2");
      expect(result.valid).toBe(true);
    });

    test("comments with leading whitespace", () => {
      const result = parseYaml("key: value\n  # indented comment\nother: val");
      expect(result.valid).toBe(true);
    });

    test("blank lines between entries", () => {
      const result = parseYaml("name: John\n\nage: 30");
      expect(result.valid).toBe(true);
    });

    test("list item with nested mapping", () => {
      const result = parseYaml("- name: John\n- name: Jane");
      expect(result.valid).toBe(true);
    });

    test("bare list item (dash only)", () => {
      const result = parseYaml("-\n-");
      expect(result.valid).toBe(true);
    });

    test("quoted value containing hash", () => {
      const result = parseYaml('color: "#fff"');
      expect(result.valid).toBe(true);
    });

    test("quoted value containing colon", () => {
      const result = parseYaml('time: "12:30"');
      expect(result.valid).toBe(true);
    });

    test("multiple levels of dedent", () => {
