import { describe, expect, test } from "bun:test";
import { parseYaml } from "./yaml-parser";

describe("parseYaml", () => {
  describe("valid cases", () => {
    test("empty file", () => {
      const result = parseYaml("");
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("whitespace-only file", () => {
      const result = parseYaml("  \n  \n");
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("comment-only file", () => {
      const result = parseYaml("# comment\n# another");
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("simple key-value", () => {
      const result = parseYaml("name: John");
      expect(result.valid).toBe(true);
    });

    test("multiple key-values", () => {
      const result = parseYaml("name: John\nage: 30");
      expect(result.valid).toBe(true);
    });

    test("simple list", () => {
      const result = parseYaml("- item1\n- item2");
      expect(result.valid).toBe(true);
    });

    test("nested mapping", () => {
      const result = parseYaml("parent:\n  child: value");
      expect(result.valid).toBe(true);
    });

    test("nested list under key", () => {
      const result = parseYaml("items:\n  - one\n  - two");
      expect(result.valid).toBe(true);
    });

    test("deep nesting", () => {
      const result = parseYaml("a:\n  b:\n    c: d");
      expect(result.valid).toBe(true);
    });

    test("inline comments", () => {
      const result = parseYaml("key: value # comment");
      expect(result.valid).toBe(true);
    });

    test("boolean values", () => {
      const result = parseYaml("flag: true");
      expect(result.valid).toBe(true);
    });

    test("null value", () => {
      const result = parseYaml("key: null");
      expect(result.valid).toBe(true);
    });

    test("key with colon in value", () => {
      const result = parseYaml("url: http://example.com");
      expect(result.valid).toBe(true);
    });

    test("quoted string value with double quotes", () => {
      const result = parseYaml('name: "John Doe"');
      expect(result.valid).toBe(true);
    });

    test("quoted string value with single quotes", () => {
      const result = parseYaml("name: 'John Doe'");
      expect(result.valid).toBe(true);
    });

    test("key with empty value (trailing colon)", () => {
      const result = parseYaml("key:");
      expect(result.valid).toBe(true);
    });

    test("dedent to previous valid level", () => {
      const result = parseYaml("a:\n  b: 1\nc: 2");
      expect(result.valid).toBe(true);
    });

    test("comments with leading whitespace", () => {
      const result = parseYaml("key: value\n  # indented comment\nother: val");
      expect(result.valid).toBe(true);
    });

    test("blank lines between entries", () => {
      const result = parseYaml("name: John\n\nage: 30");
      expect(result.valid).toBe(true);
    });

    test("list item with nested mapping", () => {
      const result = parseYaml("- name: John\n- name: Jane");
      expect(result.valid).toBe(true);
    });

    test("bare list item (dash only)", () => {
      const result = parseYaml("-\n-");
      expect(result.valid).toBe(true);
    });

    test("quoted value containing hash", () => {
      const result = parseYaml('color: "#fff"');
      expect(result.valid).toBe(true);
    });

    test("quoted value containing colon", () => {
      const result = parseYaml('time: "12:30"');
      expect(result.valid).toBe(true);
    });

    test("multiple levels of dedent", () => {
      const result = parseYaml("a:\n  b:\n    c: 1\nd: 2");
      expect(result.valid).toBe(true);
    });

    test("list under nested key", () => {
      const result = parseYaml("root:\n  items:\n    - one\n    - two");
      expect(result.valid).toBe(true);
    });
  });

  describe("invalid cases", () => {
    test("inconsistent indentation", () => {
      const result = parseYaml("a:\n  b: 1\n   c: 2");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.message).toContain("indentation");
      expect(result.error!.line).toBe(3);
    });

    test("missing colon (bare words)", () => {
      const result = parseYaml("not a valid line");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.message).toContain("syntax");
      expect(result.error!.line).toBe(1);
    });

    test("tab indentation", () => {
      const result = parseYaml("\tkey: val");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.message).toContain("Tab");
      expect(result.error!.line).toBe(1);
    });

    test("dedent to invalid level", () => {
      const result = parseYaml("a:\n    b: 1\n  c: 2");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.message).toContain("indentation");
      expect(result.error!.line).toBe(3);
    });

    test("bare word on second line", () => {
      const result = parseYaml("key: value\njust words");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.message).toContain("syntax");
      expect(result.error!.line).toBe(2);
    });

    test("tab in middle of indentation", () => {
      const result = parseYaml("a:\n  \tb: 1");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.message).toContain("Tab");
      expect(result.error!.line).toBe(2);
    });

    test("deeper indent after inline value (not allowed)", () => {
      const result = parseYaml("key: value\n  nested: bad");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.message).toContain("indentation");
      expect(result.error!.line).toBe(2);
    });
  });
});

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { parseYaml } from "./yaml-parser";

const filePath = process.argv[2];

if (!filePath) {
  process.stderr.write("Usage: bun run validate <file>\n");
  process.exit(2);
}

const resolvedPath = resolve(filePath);

let content: string;
try {
  content = readFileSync(resolvedPath, "utf-8");
} catch (err: unknown) {
  const error = err as NodeJS.ErrnoException;
  if (error.code === "ENOENT") {
    process.stderr.write(`Error: File not found: ${filePath}\n`);
  } else if (error.code === "EACCES") {
    process.stderr.write(`Error: Cannot read file: ${filePath}\n`);
  } else {
    process.stderr.write(`Error: ${error.message}\n`);
  }
  process.exit(2);
}

const result = parseYaml(content);

if (result.valid) {
  process.stdout.write(`${filePath} is valid\n`);
  process.exit(0);
} else {
  process.stderr.write(
    `${filePath} is invalid: ${result.error!.message} (line ${result.error!.line})\n`
  );
  process.exit(1);
}

import { describe, expect, test, beforeAll, afterAll } from "bun:test";
import { mkdirSync, writeFileSync, unlinkSync, rmSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";

const CLI_PATH = join(import.meta.dir, "validate-yaml.ts");
const TMP_DIR = join(tmpdir(), "yaml-validator-test-" + Date.now());

async function runCli(args: string[]): Promise<{
  stdout: string;
  stderr: string;
  exitCode: number;
}> {
  const proc = Bun.spawn(["bun", "run", CLI_PATH, ...args], {
    stdout: "pipe",
    stderr: "pipe",
  });

  const stdout = await new Response(proc.stdout).text();
  const stderr = await new Response(proc.stderr).text();
  const exitCode = await proc.exited;

  return { stdout, stderr, exitCode };
}

beforeAll(() => {
  mkdirSync(TMP_DIR, { recursive: true });
});

afterAll(() => {
  rmSync(TMP_DIR, { recursive: true, force: true });
});

describe("validate-yaml CLI", () => {
  test("no arguments outputs usage and exits with code 2", async () => {
    const { stdout, stderr, exitCode } = await runCli([]);
    expect(stderr).toContain("Usage");
    expect(stdout).toBe("");
    expect(exitCode).toBe(2);
  });

  test("nonexistent file outputs not found and exits with code 2", async () => {
    const { stdout, stderr, exitCode } = await runCli(["/nonexistent/path/file.yaml"]);
    expect(stderr).toContain("not found");
    expect(stdout).toBe("");
    expect(exitCode).toBe(2);
  });

  test("valid YAML file outputs valid and exits with code 0", async () => {
    const filePath = join(TMP_DIR, "valid.yaml");
    writeFileSync(filePath, "name: John\nage: 30\n", "utf-8");

    const { stdout, stderr, exitCode } = await runCli([filePath]);
    expect(stdout).toContain("valid");
    expect(exitCode).toBe(0);
  });

  test("invalid YAML file outputs invalid and exits with code 1", async () => {
    const filePath = join(TMP_DIR, "invalid.yaml");
    writeFileSync(filePath, "not a valid line\n", "utf-8");

    const { stdout, stderr, exitCode } = await runCli([filePath]);
    expect(stderr).toContain("invalid");
    expect(exitCode).toBe(1);
  });

  test("empty file outputs valid and exits with code 0", async () => {
    const filePath = join(TMP_DIR, "empty.yaml");
    writeFileSync(filePath, "", "utf-8");

    const { stdout, stderr, exitCode } = await runCli([filePath]);
    expect(stdout).toContain("valid");
    expect(exitCode).toBe(0);
  });
});

