        "content": "/**\n * DISPOSABLE PROTOTYPE - Hypothesis HYP-001 Validation Test Suite\n * Tests whether the hand-written YAML validator handles common config patterns.\n */\n\nimport { describe, test, expect } from \"bun:test\";\nimport { validateYaml } from \"./validate-yaml\";\n\n// ============================================================\n// SECTION 1: Basic valid YAML patterns\n// ============================================================\ndescribe(\"Valid YAML - Basic Patterns\", () => {\n  test(\"empty string is valid\", () => {\n    const result = validateYaml(\"\");\n    expect(result.valid).toBe(true);\n    expect(result.errors).toHaveLength(0);\n  });\n\n  test(\"whitespace-only is valid\", () => {\n    const result = validateYaml(\"   \\n  \\n   \");\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"comment-only is valid\", () => {\n    const result = validateYaml(\"# This is a comment\\n# Another comment\");\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"simple key-value pair\", () => {\n    const result = validateYaml(\"name: John\");\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"multiple key-value pairs\", () => {\n    const yaml = `name: John\nage: 30\nactive: true`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"key with no value (null)\", () => {\n    const yaml = `name:\ndescription:`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"document markers\", () => {\n    const yaml = `---\nname: test\n...`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"boolean, null, numeric values\", () => {\n    const yaml = `enabled: true\ndisabled: false\ncount: 42\nratio: 3.14\nnothing: null\nempty: ~`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n});\n\n// ============================================================\n// SECTION 2: Nested mappings (2+ levels)\n// ============================================================\ndescribe(\"Valid YAML - Nested Mappings\", () => {\n  test(\"two-level nesting\", () => {\n    const yaml = `server:\n  host: localhost\n  port: 8080`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"three-level nesting\", () => {\n    const yaml = `database:\n  primary:\n    host: db.example.com\n    port: 5432\n  replica:\n    host: db-replica.example.com\n    port: 5432`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"deep nesting (4+ levels)\", () => {\n    const yaml = `level1:\n  level2:\n    level3:\n      level4:\n        value: deep`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n});\n\n// ============================================================\n// SECTION 3: Sequences (lists)\n// ============================================================\ndescribe(\"Valid YAML - Sequences\", () => {\n  test(\"simple list\", () => {\n    const yaml = `fruits:\n  - apple\n  - banana\n  - cherry`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"top-level list\", () => {\n    const yaml = `- item1\n- item2\n- item3`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"list of mappings\", () => {\n    const yaml = `users:\n  - name: Alice\n    age: 30\n  - name: Bob\n    age: 25`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"nested list of mappings\", () => {\n    const yaml = `teams:\n  - name: Backend\n    members:\n      - name: Alice\n        role: Lead\n      - name: Bob\n        role: Developer\n  - name: Frontend\n    members:\n      - name: Charlie\n        role: Lead`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n});\n\n// ============================================================\n// SECTION 4: Quoted strings\n// ============================================================\ndescribe(\"Valid YAML - Quoted Strings\", () => {\n  test(\"double-quoted values\", () => {\n    const yaml = `name: \"John Doe\"\nmessage: \"Hello, world!\"`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"single-quoted values\", () => {\n    const yaml = `name: 'John Doe'\npath: '/usr/local/bin'`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"quoted keys\", () => {\n    const yaml = `\"special key\": value\n'another key': value`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"values with special characters in quotes\", () => {\n    const yaml = `regex: \"^[a-z]+$\"\npath: \"C:\\\\Users\\\\test\"\ncolon: \"key: value\"`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n});\n\n// ============================================================\n// SECTION 5: Multi-line scalars\n// ============================================================\ndescribe(\"Valid YAML - Multi-line Scalars\", () => {\n  test(\"literal block scalar (|)\", () => {\n    const yaml = `description: |\n  This is a multi-line\n  description that preserves\n  newlines.`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"folded block scalar (>)\", () => {\n    const yaml = `description: >\n  This is a multi-line\n  description that folds\n  newlines into spaces.`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"block scalar with chomping indicator (|-, >+)\", () => {\n    const yaml = `strip: |-\n  no trailing newline\nkeep: >+\n  keep trailing newlines`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"block scalar followed by more keys\", () => {\n    const yaml = `description: |\n  Multi-line content\n  goes here.\nname: after-block\nversion: 1.0`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n});\n\n// ============================================================\n// SECTION 6: Comments\n// ============================================================\ndescribe(\"Valid YAML - Comments\", () => {\n  test(\"inline comments\", () => {\n    const yaml = `name: John  # the user's name\nage: 30     # in years`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"comment between entries\", () => {\n    const yaml = `# Server config\nserver:\n  # Host setting\n  host: localhost\n  # Port setting\n  port: 8080`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n});\n\n// ============================================================\n// SECTION 7: Real-world config file patterns\n// ============================================================\ndescribe(\"Valid YAML - Docker Compose Pattern\", () => {\n  test(\"typical docker-compose.yml\", () => {\n    const yaml = `version: \"3.8\"\nservices:\n  web:\n    image: nginx:latest\n    ports:\n      - \"80:80\"\n      - \"443:443\"\n    volumes:\n      - ./html:/usr/share/nginx/html\n    environment:\n      - NGINX_HOST=example.com\n      - NGINX_PORT=80\n    depends_on:\n      - api\n    restart: always\n  api:\n    build:\n      context: .\n      dockerfile: Dockerfile\n    ports:\n      - \"3000:3000\"\n    environment:\n      NODE_ENV: production\n      DB_HOST: db\n    depends_on:\n      - db\n  db:\n    image: postgres:15\n    volumes:\n      - pgdata:/var/lib/postgresql/data\n    environment:\n      POSTGRES_DB: myapp\n      POSTGRES_USER: admin\n      POSTGRES_PASSWORD: secret\nvolumes:\n  pgdata:`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n    expect(result.errors).toHaveLength(0);\n  });\n});\n\ndescribe(\"Valid YAML - GitHub Actions Pattern\", () => {\n  test(\"typical GitHub Actions workflow\", () => {\n    const yaml = `name: CI\non:\n  push:\n    branches:\n      - main\n      - develop\n  pull_request:\n    branches:\n      - main\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - name: Setup Node.js\n        uses: actions/setup-node@v4\n        with:\n          node-version: \"20\"\n          cache: npm\n      - name: Install dependencies\n        run: npm ci\n      - name: Run tests\n        run: npm test\n      - name: Build\n        run: npm run build\n  deploy:\n    needs: build\n    runs-on: ubuntu-latest\n    if: github.ref == 'refs/heads/main'\n    steps:\n      - uses: actions/checkout@v4\n      - name: Deploy\n        run: |\n          echo \"Deploying...\"\n          ./deploy.sh`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n    expect(result.errors).toHaveLength(0);\n  });\n});\n\ndescribe(\"Valid YAML - Kubernetes Manifest Pattern\", () => {\n  test(\"typical Kubernetes Deployment\", () => {\n    const yaml = `---\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: my-app\n  namespace: default\n  labels:\n    app: my-app\n    version: \"1.0\"\nspec:\n  replicas: 3\n  selector:\n    matchLabels:\n      app: my-app\n  template:\n    metadata:\n      labels:\n        app: my-app\n    spec:\n      containers:\n        - name: my-app\n          image: my-app:latest\n          ports:\n            - containerPort: 8080\n          env:\n            - name: DB_HOST\n              value: \"postgres.default.svc\"\n            - name: DB_PORT\n              value: \"5432\"\n          resources:\n            requests:\n              cpu: \"100m\"\n              memory: \"128Mi\"\n            limits:\n              cpu: \"500m\"\n              memory: \"512Mi\"\n          livenessProbe:\n            httpGet:\n              path: /health\n              port: 8080\n            initialDelaySeconds: 10\n            periodSeconds: 30\n          readinessProbe:\n            httpGet:\n              path: /ready\n              port: 8080\n            initialDelaySeconds: 5\n            periodSeconds: 10`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n    expect(result.errors).toHaveLength(0);\n  });\n\n  test(\"Kubernetes Service\", () => {\n    const yaml = `apiVersion: v1\nkind: Service\nmetadata:\n  name: my-service\nspec:\n  type: ClusterIP\n  selector:\n    app: my-app\n  ports:\n    - port: 80\n      targetPort: 8080\n      protocol: TCP`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n});\n\ndescribe(\"Valid YAML - Additional Real-World Patterns\", () => {\n  test(\"Ansible playbook pattern\", () => {\n    const yaml = `---\n- hosts: webservers\n  become: true\n  vars:\n    http_port: 80\n    max_clients: 200\n  tasks:\n    - name: Ensure Apache is installed\n      apt:\n        name: apache2\n        state: present\n    - name: Start Apache service\n      service:\n        name: apache2\n        state: started\n        enabled: true`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"GitLab CI pattern\", () => {\n    const yaml = `stages:\n  - build\n  - test\n  - deploy\nbuild:\n  stage: build\n  script:\n    - npm ci\n    - npm run build\n  artifacts:\n    paths:\n      - dist/\ntest:\n  stage: test\n  script:\n    - npm test\n  coverage: '/Statements.*?(\\\\d+\\\\.?\\\\d+)%/'\ndeploy:\n  stage: deploy\n  script:\n    - ./deploy.sh\n  only:\n    - main`;\n    const result = validateYaml(yaml);\n    expect(result.valid).toBe(true);\n  });\n\n  test(\"ESLint config YAML pattern\", () => {\n    const yaml = `root: true\nenv:\n  node: true\n  es2022: true\nextends:\n  - eslint:recommended\nrules:\n  no-unused-vars: warn\n  no-console: off\n  semi:\n    - error\n    - always`;\n    const result = validateYaml(yaml);\n    expect(r