calar Stress Test ===\");\nlet blockYaml = \"\";\nfor (let i = 0; i < 100; i++) {\n  blockYaml += `field_${i}: |\\n  Line 1 of field ${i}\\n  Line 2 of field ${i}\\n`;\n}\nconst blockResult = validateYaml(blockYaml);\nconsole.log(`100 block scalars: Valid=${blockResult.valid}, Errors=${blockResult.errors.length}`);\n\n// Edge case: Kubernetes-like multi-container pod spec\nconsole.log(\"\\n=== Complex K8s Pod Spec ===\");\nconst k8sYaml = `apiVersion: v1\nkind: Pod\nmetadata:\n  name: multi-container-pod\n  labels:\n    app: multi-container\n    environment: production\n  annotations:\n    description: \"A pod with multiple containers\"\nspec:\n  initContainers:\n    - name: init-db\n      image: busybox:latest\n      command:\n        - sh\n        - -c\n        - \"until nslookup db; do echo waiting; sleep 2; done\"\n  containers:\n    - name: app\n      image: my-app:v2.1.0\n      ports:\n        - containerPort: 8080\n          name: http\n          protocol: TCP\n        - containerPort: 9090\n          name: metrics\n      env:\n        - name: DATABASE_URL\n          valueFrom:\n            secretKeyRef:\n              name: db-secret\n              key: url\n        - name: LOG_LEVEL\n          value: \"info\"\n      volumeMounts:\n        - name: config-vol\n          mountPath: /etc/config\n          readOnly: true\n      resources:\n        requests:\n          cpu: \"250m\"\n          memory: \"256Mi\"\n        limits:\n          cpu: \"1\"\n          memory: \"1Gi\"\n      livenessProbe:\n        httpGet:\n          path: /healthz\n          port: 8080\n        initialDelaySeconds: 15\n        periodSeconds: 20\n      readinessProbe:\n        httpGet:\n          path: /readyz\n          port: 8080\n        initialDelaySeconds: 5\n        periodSeconds: 10\n    - name: sidecar\n      image: envoy:latest\n      ports:\n        - containerPort: 15001\n  volumes:\n    - name: config-vol\n      configMap:\n        name: app-config\n  restartPolicy: Always\n  terminationGracePeriodSeconds: 30`;\nconst k8sResult = validateYaml(k8sYaml);\nconsole.log(`K8s Pod spec: Valid=${k8sResult.valid}, Errors=${k8sResult.errors.length}`);\nif (k8sResult.errors.length > 0) {\n  console.log(\"Errors:\", JSON.stringify(k8sResult.errors, null, 2));\n}\n\n// Edge case: GitHub Actions with complex multi-line run blocks\nconsole.log(\"\\n=== GitHub Actions Complex ===\");\nconst ghaYaml = `name: Release\non:\n  push:\n    tags:\n      - \"v*.*.*\"\npermissions:\n  contents: write\n  packages: write\njobs:\n  release:\n    runs-on: ubuntu-latest\n    strategy:\n      matrix:\n        node-version: [18, 20, 22]\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n      - name: Setup Node\n        uses: actions/setup-node@v4\n        with:\n          node-version: \\${{ matrix.node-version }}\n      - run: npm ci\n      - run: npm test\n      - name: Build and publish\n        run: |\n          npm run build\n          echo \"Publishing...\"\n          npm publish --access public\n        env:\n          NODE_AUTH_TOKEN: \\${{ secrets.NPM_TOKEN }}`;\nconst ghaResult = validateYaml(ghaYaml);\nconsole.log(`GHA workflow: Valid=${ghaResult.valid}, Errors=${ghaResult.errors.length}`);\nif (ghaResult.errors.length > 0) {\n  console.log(\"Errors:\", JSON.stringify(ghaResult.errors, null, 2));\n}\n\n// Test false-positive: ensure valid YAML isn't rejected\nconsole.log(\"\\n=== False Positive Check ===\");\nconst falsePositiveTests = [\n  { name: \"URL with colon\", yaml: 'url: \"https://example.com:8080\"' },\n  { name: \"Time value\", yaml: \"time: 12:30:00\" },\n  { name: \"Colon in value\", yaml: 'msg: \"Error: something failed\"' },\n  { name: \"Multiline with special chars\", yaml: \"script: |\\n  echo 'hello'\\n  echo \\\"world\\\"\" },\n  { name: \"List with inline map\", yaml: \"items:\\n  - {name: a, value: 1}\\n  - {name: b, value: 2}\" },\n  { name: \"Empty mapping value\", yaml: \"config:\\n  sub:\\n    key:\" },\n  { name: \"Hyphenated key\", yaml: \"my-key: my-value\" },\n  { name: \"Underscore key\", yaml: \"my_key: my_value\" },\n  { name: \"Numeric key-like\", yaml: \"123: numeric key\" },\n  { name: \"Boolean values\", yaml: \"a: true\\nb: false\\nc: yes\\nd: no\\ne: on\\nf: off\" },\n];\n\nlet fpPass = 0;\nlet fpFail = 0;\nfor (const t of falsePositiveTests) {\n  const r = validateYaml(t.yaml);\n  if (r.valid) {\n    fpPass++;\n  } else {\n    fpFail++;\n    console.log(`  FALSE POSITIVE: \"${t.name}\" rejected: ${JSON.stringify(r.errors)}`);\n  }\n}\nconsole.log(`False positive check: ${fpPass}/${falsePositiveTests.length} passed`);\n\n// Test false-negative: ensure invalid YAML is rejected\nconsole.log(\"\\n=== False Negative Check ===\");\nconst falseNegativeTests = [\n  { name: \"Tab indent\", yaml: \"key:\\n\\tvalue: 1\" },\n  { name: \"Unclosed double quote\", yaml: 'key: \"unclosed' },\n  { name: \"Unclosed single quote\", yaml: \"key: 'unclosed\" },\n  { name: \"Unbalanced brace\", yaml: \"key: {a: 1, b: 2\" },\n  { name: \"Unbalanced bracket\", yaml: \"key: [1, 2, 3\" },\n];\n\nlet fnPass = 0;\nlet fnFail = 0;\nfor (const t of falseNegativeTests) {\n  const r = validateYaml(t.yaml);\n  if (!r.valid) {\n    fnPass++;\n  } else {\n    fnFail++;\n    console.log(`  FALSE NEGATIVE: \"${t.name}\" accepted but should be rejected`);\n  }\n}\nconsole.log(`False negative check: ${fnPass}/${falseNegativeTests.length} passed`);\n\nconsole.log(\"\\n=== OVERALL RESULTS ===\");\nconsole.log(`Performance: ${avgTime.toFixed(2)}ms avg for ${lineCount}-line file (target: <1000ms)`);\nconsole.log(`False positives: ${fpFail} (valid YAML incorrectly rejected)`);\nconsole.log(`False negatives: ${fnFail} (invalid YAML incorrectly accepted)`);\nconsole.log(`Verdict: ${fpFail === 0 && fnFail === 0 ? \"ALL CHECKS PASSED\" : \"SOME CHECKS FAILED\"}`);\n"
