ml: \"k: |\\n  line1\\n  line2\", expectValid: true },\n      { name: \"block scalar >\", yaml: \"k: >\\n  line1\\n  line2\", expectValid: true },\n      { name: \"comment\", yaml: \"# comment\\nk: v\", expectValid: true },\n      { name: \"doc marker\", yaml: \"---\\nk: v\\n...\", expectValid: true },\n      { name: \"tab indent\", yaml: \"k:\\n\\tv: 1\", expectValid: false },\n      { name: \"unclosed quote\", yaml: 'k: \"unclosed', expectValid: false },\n    ];\n\n    let passed = 0;\n    let failed = 0;\n    const failures: string[] = [];\n\n    for (const tc of testCases) {\n      const result = validateYaml(tc.yaml);\n      if (result.valid === tc.expectValid) {\n        passed++;\n      } else {\n        failed++;\n        failures.push(`${tc.name}: expected valid=${tc.expectValid}, got valid=${result.valid}`);\n      }\n    }\n\n    console.log(`\\n=== Validation Summary ===`);\n    console.log(`Total: ${testCases.length}, Passed: ${passed}, Failed: ${failed}`);\n    if (failures.length > 0) {\n      console.log(`Failures:`);\n      failures.forEach((f) => console.log(`  - ${f}`));\n    }\n\n    expect(failed).toBe(0);\n  });\n});\n"
