});\ncheck(\"fmt-col\", e === \"  Line 5, Column 3: Tab found\", e);\n\n// 13. formatValidationError without column\ne = formatValidationError({ line: 10, message: \"Bad syntax\" });\ncheck(\"fmt-nocol\", e === \"  Line 10: Bad syntax\", e);\n\n// 14. Only whitespace\nr = validateYaml(\"   \\n\\n  \");\ncheck(\"whitespace\", r.valid === true, JSON.stringify(r));\n\n// 15. Only comments\nr = validateYaml(\"# just a comment\\n# another comment\");\ncheck(\"comments-only\", r.valid === true, JSON.stringify(r));\n\n// 16. Scalar types\nr = validateYaml(\"enabled: true\\ncount: 42\\nnothing: null\\nratio: 3.14\");\ncheck(\"scalars\", r.valid === true, JSON.stringify(r));\n\n// 17. Valid flow\nr = validateYaml(\"{name: John, age: 30}\");\ncheck(\"flow-valid\", r.valid === true, JSON.stringify(r));\n\n// 18. Unbalanced flow\nr = validateYaml(\"{name: John, age: 30\");\ncheck(\"flow-unbal\", r.valid === false, JSON.stringify(r));\n\n// 19. Apostrophe in comment\nr = validateYaml(\"name: John  # the user'\\''s name\");\ncheck(\"apostrophe-comment\", r.valid === true, JSON.stringify(r));\n\n// 20. Single scalar\nr = validateYaml(\"hello world\");\ncheck(\"single-scalar\", r.valid === true, JSON.stringify(r));\n\n// 21. CRLF\nr = validateYaml(\"name: John\\r\\nage: 30\\r\\n\");\ncheck(\"crlf\", r.valid === true, JSON.stringify(r));\n\n// 22. Folded scalar\nr = validateYaml(\"description: >\\n  This is a\\n  folded text\");\ncheck(\"folded\", r.valid === true, JSON.stringify(r));\n\n// 23. Block scalar with chomping\nr = validateYaml(\"description: |-\\n  stripped\\n  text\");\ncheck(\"chomp\", r.valid === true, JSON.stringify(r));\n\n// 24. URL in value\nr = validateYaml(\"url: https://example.com\");\ncheck(\"url\", r.valid === true, JSON.stringify(r));\n\n// 25. Docker Compose\nr = validateYaml(`version: \"3.8\"\nservices:\n  web:\n    image: nginx:latest\n    ports:\n      - \"80:80\"\n    volumes:\n      - ./html:/usr/share/nginx/html\n  db:\n    image: postgres:15\n    environment:\n      POSTGRES_DB: mydb\n      POSTGRES_USER: admin`);\ncheck(\"docker-compose\", r.valid === true, JSON.stringify(r));\n\n// 26. GitHub Actions\nr = validateYaml(`name: CI\non:\n  push:\n    branches:\n      - main\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - name: Run tests\n        run: npm test`);\ncheck(\"gha\", r.valid === true, JSON.stringify(r));\n\n// 27. File not found\nconst vf = await validateYamlFile(\"/tmp/does-not-exist-yaml-test.yaml\");\ncheck(\"file-missing\", vf.valid === false && vf.errors[0].message.includes(\"File not found\"), JSON.stringify(vf));\n\n// 28. Top-level list\nr = validateYaml(\"- item1\\n- item2\\n- item3\");\ncheck(\"top-list\", r.valid === true, JSON.stringify(r));\n\n// 29. K8s\nr = validateYaml(`apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: nginx\n  labels:\n    app: nginx\nspec:\n  replicas: 3\n  selector:\n    matchLabels:\n      app: nginx\n  template:\n    metadata:\n      labels:\n        app: nginx\n    spec:\n      containers:\n        - name: nginx\n          image: nginx:1.21\n          ports:\n            - containerPort: 80`);\ncheck(\"k8s\", r.valid === true, JSON.stringify(r));\n\n// 30. Block scalar followed by more keys\nr = validateYaml(`description: |\n  Some text here\n  more text\nname: after-block`);\ncheck(\"block-then-key\", r.valid === true, JSON.stringify(r));\n\n// 31. Folded with chomping indicator >+\nr = validateYaml(\"msg: >+\\n  keep\\n  newlines\");\ncheck(\"folded-chomp\", r.valid === true, JSON.stringify(r));\n\n// 32. Multi-document\nr = validateYaml(\"---\\nname: doc1\\n---\\nname: doc2\");\ncheck(\"multi-doc\", r.valid === true, JSON.stringify(r));\n\n// 33. Unbalanced bracket\nr = validateYaml(\"[item1, item2\");\ncheck(\"unbal-bracket\", r.valid === false, JSON.stringify(r));\n\n// 34. Unclosed single quote\nr = validateYaml(\"name: '\\''unclosed\");\ncheck(\"unclosed-sq\", r.valid === false, JSON.stringify(r));\n\n// 35. Sequence entry with block scalar\nr = validateYaml(\"items:\\n  - text: |\\n      hello\\n      world\\n  - text: simple\");\ncheck(\"seq-block-scalar\", r.valid === true, JSON.stringify(r));\n\n// 36. validateYamlFile with valid file\nimport { writeFileSync, unlinkSync } from \"fs\";\nconst tmpFile = \"/tmp/yaml-validator-test-valid.yaml\";\nwriteFileSync(tmpFile, \"name: test\\nage: 30\\n\");\nconst vfValid = await validateYamlFile(tmpFile);\ncheck(\"file-valid\", vfValid.valid === true, JSON.stringify(vfValid));\nunlinkSync(tmpFile);\n\n// 37. validateYamlFile with invalid content\nconst tmpFile2 = \"/tmp/yaml-validator-test-invalid.yaml\";\nwriteFileSync(tmpFile2, \"name: \\\"unclosed\\n\");\nconst vfInvalid = await validateYamlFile(tmpFile2);\ncheck(\"file-invalid\", vfInvalid.valid === false, JSON.stringify(vfInvalid));\nunlinkSync(tmpFile2);\n\nconsole.log(`\\nResults: ${passed} passed, ${failed} failed out of ${passed + failed}`);\n'\n",
