t-col\", e === \"  Line 5, Column 3: Tab found\", e);\n\n// 13. formatValidationError without column\ne = formatValidationError({ line: 10, message: \"Bad syntax\" });\ncheck(\"fmt-nocol\", e === \"  Line 10: Bad syntax\", e);\n\n// 14. Only whitespace\nr = validateYaml(\"   \\n\\n  \");\ncheck(\"whitespace\", r.valid === true, JSON.stringify(r));\n\n// 15. Only comments\nr = validateYaml(\"# just a comment\\n# another comment\");\ncheck(\"comments-only\", r.valid === true, JSON.stringify(r));\n\n// 16. Scalar types\nr = validateYaml(\"enabled: true\\ncount: 42\\nnothing: null\\nratio: 3.14\");\ncheck(\"scalars\", r.valid === true, JSON.stringify(r));\n\n// 17. Valid flow\nr = validateYaml(\"{name: John, age: 30}\");\ncheck(\"flow-valid\", r.valid === true, JSON.stringify(r));\n\n// 18. Unbalanced flow\nr = validateYaml(\"{name: John, age: 30\");\ncheck(\"flow-unbal\", r.valid === false, JSON.stringify(r));\n\n// 19. Apostrophe in comment\nr = validateYaml(\"name: John  # the user'\\''s name\");\ncheck(\"apostrophe-comment\", r.valid === true, JSON.stringify(r));\n\n// 20. Single scalar\nr = validateYaml(\"hello world\");\ncheck(\"single-scalar\", r.valid === true, JSON.stringify(r));\n\n// 21. CRLF\nr = validateYaml(\"name: John\\r\\nage: 30\\r\\n\");\ncheck(\"crlf\", r.valid === true, JSON.stringify(r));\n\n// 22. Folded scalar\nr = validateYaml(\"description: >\\n  This is a\\n  folded text\");\ncheck(\"folded\", r.valid === true, JSON.stringify(r));\n\n// 23. Block scalar with chomping\nr = validateYaml(\"description: |-\\n  stripped\\n  text\");\ncheck(\"chomp\", r.valid === true, JSON.stringify(r));\n\n// 24. URL in value\nr = validateYaml(\"url: https://example.com\");\ncheck(\"url\", r.valid === true, JSON.stringify(r));\n\n// 25. Docker Compose\nr = validateYaml(`version: \"3.8\"\nservices:\n  web:\n    image: nginx:latest\n    ports:\n      - \"80:80\"\n    volumes:\n      - ./html:/usr/share/nginx/html\n  db:\n    image: postgres:15\n    environment:\n   