        "file_path": "/tmp/hypothesis-yaml-validator-command/validate-yaml.ts",
        "content": "/**\n * DISPOSABLE PROTOTYPE - Hypothesis HYP-001 Validation\n * Hand-written YAML syntax validator (no external dependencies)\n * Tests whether a line-by-line approach can handle common YAML config patterns.\n */\n\nexport interface ValidationError {\n  line: number;\n  column?: number;\n  message: string;\n}\n\nexport interface ValidationResult {\n  valid: boolean;\n  errors: ValidationError[];\n}\n\ninterface ParseState {\n  /** Stack of indentation levels */\n  indentStack: number[];\n  /** Whether we are inside a block scalar (| or >) */\n  inBlockScalar: boolean;\n  /** The indentation level of the block scalar indicator line */\n  blockScalarIndent: number;\n  /** Whether the block scalar has received at least one content line */\n  blockScalarHasContent: boolean;\n  /** Whether we are on the first content line of the document */\n  hasContent: boolean;\n  /** Track keys at each indentation level for duplicate detection */\n  keysAtLevel: Map<number, Set<string>>;\n}\n\nfunction isBlankOrComment(line: string): boolean {\n  const trimmed = line.trimStart();\n  return trimmed === \"\" || trimmed.startsWith(\"#\");\n}\n\nfunction getIndentation(line: string): number {\n  let count = 0;\n  for (const ch of line) {\n    if (ch === \" \") count++;\n    else break;\n  }\n  return count;\n}\n\nfunction hasTabIndentation(line: string): boolean {\n  for (const ch of line) {\n    if (ch === \"\\t\") return true;\n    if (ch !== \" \") break;\n  }\n  return false;\n}\n\nfunction isDocumentMarker(trimmed: string): boolean {\n  return trimmed === \"---\" || trimmed === \"...\";\n}\n\nfunction isSequenceItem(trimmed: string): boolean {\n  return trimmed === \"-\" || trimmed.startsWith(\"- \");\n}\n\n/**\n * Check if a string has balanced quotes.\n * This handles escaped quotes within strings.\n */\nfunction hasBalancedQuotes(line: string): { balanced: boolean; quoteChar?: string } {\n  let inSingle = false;\n  let inDouble = false;\n  for (let i = 0; i < line.length; i++) {\n    const ch = line[i];\n    const prev = i > 0 ? line[i - 1] : \"\";\n    if (ch === \"'\" && !inDouble && prev !== \"\\\\\") {\n      inSingle = !inSingle;\n    } else if (ch === '\"' && !inSingle && prev !== \"\\\\\") {\n      inDouble = !inDouble;\n    }\n  }\n  if (inSingle) return { balanced: false, quoteChar: \"'\" };\n  if (inDouble) return { balanced: false, quoteChar: '\"' };\n  return { balanced: true };\n}\n\n/**\n * Check if a line looks like a mapping entry (key: value).\n * Handles quoted keys and various value types.\n */\nfunction isMappingEntry(trimmed: string): boolean {\n  // Handle quoted keys\n  if (trimmed.startsWith('\"') || trimmed.startsWith(\"'\")) {\n    const quoteChar = trimmed[0];\n    let i = 1;\n    while (i < trimmed.length) {\n      if (trimmed[i] === \"\\\\\" && i + 1 < trimmed.length) {\n        i += 2;\n        continue;\n      }\n      if (trimmed[i] === quoteChar) {\n        // After closing quote, expect ':'\n        const rest = trimmed.substring(i + 1).trimStart();\n        return rest.startsWith(\":\");\n      }\n      i++;\n    }\n    return false;\n  }\n\n  // Handle unquoted keys - look for first unquoted colon followed by space or end of line\n  // But skip colons inside flow mappings/sequences\n  let braceDepth = 0;\n  let bracketDepth = 0;\n  for (let i = 0; i < trimmed.length; i++) {\n    const ch = trimmed[i];\n    if (ch === \"{\") braceDepth++;\n    else if (ch === \"}\") braceDepth--;\n    else if (ch === \"[\") bracketDepth++;\n    else if (ch === \"]\") bracketDepth--;\n    else if (ch === \":\" && braceDepth === 0 && bracketDepth === 0) {\n      // Colon must be followed by space, end of line, or be at end\n      if (i + 1 >= trimmed.length || trimmed[i + 1] === \" \" || trimmed[i + 1] === \"\\t\") {\n        return true;\n      }\n    }\n  }\n  return false;\n}\n\n/**\n * Extract the key from a mapping entry line.\n */\nfunction extractKey(trimmed: string): string | null {\n  if (trimmed.startsWith('\"') || trimmed.startsWith(\"'\")) {\n    const quoteChar = trimmed[0];\n    let i = 1;\n    while (i < trimmed.length) {\n      if (trimmed[i] === \"\\\\\" && i + 1 < trimmed.length) {\n        i += 2;\n        continue;\n      }\n      if (trimmed[i] === quoteChar) {\n        return trimmed.substring(1, i);\n      }\n      i++;\n    }\n    return null;\n  }\n  const colonIdx = trimmed.indexOf(\": \");\n  if (colonIdx === -1) {\n    // key with no value (key:)\n    if (trimmed.endsWith(\":\")) {\n      return trimmed.slice(0, -1).trim();\n    }\n    return null;\n  }\n  return trimmed.substring(0, colonIdx).trim();\n}\n\n/**\n * Check if a value is a block scalar indicator (| or >), optionally with modifiers.\n */\nfunction isBlockScalarIndicator(value: string): boolean {\n  const trimmedValue = value.trim();\n  if (trimmedValue === \"\") return false;\n  // Remove any trailing comment\n  const withoutComment = trimmedValue.split(\"#\")[0].trim();\n  // Block scalar indicators: |, >, |+, |-, >+, >-, |2, >2, etc.\n  return /^[|>][+-]?\\d*$/.test(withoutComment) || /^[|>]\\d+[+-]?$/.test(withoutComment);\n}\n\n/**\n * Get the value part of a mapping entry.\n */\nfunction getMappingValue(trimmed: string): string {\n  if (trimmed.startsWith('\"') || trimmed.startsWith(\"'\")) {\n    const quoteChar = trimmed[0];\n    let i = 1;\n    while (i < trimmed.length) {\n      if (trimmed[i] === \"\\\\\" && i + 1 < trimmed.length) {\n        i += 2;\n        continue;\n      }\n      if (trimmed[i] === quoteChar) {\n        const rest = trimmed.substring(i + 1).trimStart();\n        if (rest.startsWith(\":\")) {\n          return rest.substring(1).trimStart();\n        }\n        return \"\";\n      }\n      i++;\n    }\n    return \"\";\n  }\n  const colonIdx = trimmed.indexOf(\": \");\n  if (colonIdx !== -1) {\n    return trimmed.substring(colonIdx + 2).trim();\n  }\n  if (trimmed.endsWith(\":\")) {\n    return \"\";\n  }\n  return \"\";\n}\n\n/**\n * Check if a line is a flow collection (starts with { or [).\n */\nfunction isFlowCollection(trimmed: string): boolean {\n  return trimmed.startsWith(\"{\") || trimmed.startsWith(\"[\");\n}\n\n/**\n * Basic validation of flow collections (balanced braces/brackets).\n */\nfunction validateFlowCollection(trimmed: string): boolean {\n  const stack: string[] = [];\n  let inSingle = false;\n  let inDouble = false;\n  for (let i = 0; i < trimmed.length; i++) {\n    const ch = trimmed[i];\n    const prev = i > 0 ? trimmed[i - 1] : \"\";\n    if (ch === \"'\" && !inDouble && prev !== \"\\\\\") {\n      inSingle = !inSingle;\n    } else if (ch === '\"' && !inSingle && prev !== \"\\\\\") {\n      inDouble = !inDouble;\n    } else if (!inSingle && !inDouble) {\n      if (ch === \"{\" || ch === \"[\") {\n        stack.push(ch);\n      } else if (ch === \"}\") {\n        if (stack.length === 0 || stack[stack.length - 1] !== \"{\") return false;\n        stack.pop();\n      } else if (ch === \"]\") {\n        if (stack.length === 0 || stack[stack.length - 1] !== \"[\") return false;\n        stack.pop();\n      }\n    }\n  }\n  return stack.length === 0 && !inSingle && !inDouble;\n}\n\n/**\n * Check if a value part is a flow collection.\n */\nfunction valueIsFlowCollection(value: string): boolean {\n  const v = value.trim();\n  return v.startsWith(\"{\") || v.startsWith(\"[\");\n}\n\nexport function validateYaml(content: string): ValidationResult {\n  const errors: ValidationError[] = [];\n\n  // Empty content is valid YAML\n  if (content.trim() === \"\") {\n    return { valid: true, errors: [] };\n  }\n\n  const lines = content.split(\"\\n\");\n  const state: ParseState = {\n    indentStack: [0],\n    inBlockScalar: false,\n    blockScalarIndent: 0,\n    blockScalarHasContent: false,\n    hasContent: false,\n    keysAtLevel: new Map(),\n  };\n\n  for (let i = 0; i < lines.length; i++) {\n    const lineNum = i + 1;\n    const line = lines[i];\n\n    // Check for tab indentation\n    if (hasTabIndentation(line)) {\n      errors.push({\n        line: lineNum,\n        message: \"Tab character found in indentation. YAML requires spaces for indentation.\",\n      });\n      continue;\n    }\n\n    // Handle block scalar content\n    if (state.inBlockScalar) {\n      if (line.trim() === \"\") {\n        // Empty lines within block scalars are allowed\n        continue;\n      }\n      const indent = getIndentation(line);\n      if (indent > state.blockScalarIndent) {\n        // This is content of the block scalar\n        state.blockScalarHasContent = true;\n        continue;\n      } else {\n        // Block scalar ended - process this line normally\n        state.inBlockScalar = false;\n        state.blockScalarHasContent = false;\n      }\n    }\n\n    // Skip blank lines and comments\n    if (isBlankOrComment(line)) {\n      continue;\n    }\n\n    const trimmed = line.trimStart();\n    const indent = getIndentation(line);\n\n    // Document markers\n    if (isDocumentMarker(trimmed)) {\n      // Reset state for new document\n      if (trimmed === \"---\") {\n        state.indentStack = [0];\n        state.keysAtLevel = new Map();\n      }\n      continue;\n    }\n\n    // Check for content after stripping sequence marker\n    let contentTrimmed = trimmed;\n    let effectiveIndent = indent;\n\n    // Handle sequence items\n    if (isSequenceItem(trimmed)) {\n      // For \"- key: value\" patterns, adjust the content after the dash\n      if (trimmed.length > 2) {\n        contentTrimmed = trimmed.substring(2);\n      } else {\n        // Bare \"- \" or \"-\"\n        state.hasContent = true;\n        continue;\n      }\n    }\n\n    // Check unclosed quotes\n    const quoteCheck = hasBalancedQuotes(line);\n    if (!quoteCheck.balanced) {\n      errors.push({\n        line: lineNum,\n        message: `Unclosed ${quoteCheck.quoteChar === \"'\" ? \"single\" : \"double\"} quote`,\n      });\n      continue;\n    }\n\n    // Flow collections at top level or as values\n    if (isFlowCollection(contentTrimmed)) {\n      if (!validateFlowCollection(contentTrimmed)) {\n        errors.push({\n          line: lineNum,\n          message: \"Unbalanced brackets or braces in flow collection\",\n        });\n      }\n      state.hasContent = true;\n      continue;\n    }\n\n    // Mapping entries\n    if (isMappingEntry(contentTrimmed)) {\n      const value = getMappingValue(contentTrimmed);\n      // Check for block scalar indicator\n      if (isBlockScalarIndicator(value)) {\n        state.inBlockScalar = true;\n        state.blockScalarIndent = indent;\n        state.blockScalarHasContent = false;\n      } else if (valueIsFlowCollection(value)) {\n        // Validate inline flow collection\n        if (!validateFlowCollection(value)) {\n          errors.push({\n            line: lineNum,\n            message: \"Unbalanced brackets or braces in inline flow collection\",\n          });\n        }\n      }\n      state.hasContent = true;\n      continue;\n    }\n\n    // Plain scalar value (could be a list item value, continuation, etc.)\n    // If we have content and this line has proper indentation, it could be a continuation\n    if (state.hasContent) {\n      // Accept as continuation or plain value\n      continue;\n    }\n\n    // First content line can be a plain scalar\n    state.hasContent = true;\n  }\n\n  return {\n    valid: errors.length === 0,\n    errors,\n  };\n}\n"
