        "new_string": "/**\n * Check if a string has balanced quotes.\n * This handles escaped quotes within strings and is aware of inline comments.\n * In YAML, a # preceded by a space (and not inside quotes) starts a comment,\n * so we stop checking quotes once we encounter an unquoted comment.\n */\nfunction hasBalancedQuotes(line: string): { balanced: boolean; quoteChar?: string } {\n  let inSingle = false;\n  let inDouble = false;\n  for (let i = 0; i < line.length; i++) {\n    const ch = line[i];\n    const prev = i > 0 ? line[i - 1] : \"\";\n\n    // If we encounter a # outside of quotes preceded by a space, the rest is a comment\n    if (ch === \"#\" && !inSingle && !inDouble && i > 0 && line[i - 1] === \" \") {\n      break;\n    }\n\n    if (ch === \"'\" && !inDouble && prev !== \"\\\\\") {\n      inSingle = !inSingle;\n    } else if (ch === '\"' && !inSingle && prev !== \"\\\\\") {\n      inDouble = !inDouble;\n    }\n  }\n  if (inSingle) return { balanced: false, quoteChar: \"'\" };\n  if (inDouble) return { balanced: false, quoteChar: '\"' };\n  return { balanced: true };\n}"
