        "content": "import { describe, expect, test, beforeAll, afterAll } from \"bun:test\";\nimport { join } from \"path\";\nimport { mkdtemp, rm } from \"fs/promises\";\nimport { tmpdir } from \"os\";\nimport {\n  validateYaml,\n  validateYamlFile,\n  formatValidationError,\n  type ValidationError,\n} from \"./yaml-validator\";\n\ndescribe(\"validateYaml\", () => {\n  describe(\"valid YAML cases\", () => {\n    test(\"empty string returns valid\", () => {\n      const result = validateYaml(\"\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"simple key-value pair returns valid\", () => {\n      const result = validateYaml(\"name: Alice\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"nested mappings return valid\", () => {\n      const yaml = `server:\n  host: localhost\n  port: 8080\n  database:\n    name: mydb\n    user: admin`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"sequences (lists) return valid\", () => {\n      const yaml = `items:\n  - apple\n  - banana\n  - cherry`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"mixed mappings and sequences return valid\", () => {\n      const yaml = `users:\n  - name: Alice\n    role: admin\n  - name: Bob\n    role: user\nsettings:\n  debug: true`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"comments are ignored and document is valid\", () => {\n      const yaml = `# This is a comment\nname: Alice\n# Another comment\nage: 30`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"double quoted strings return valid\", () => {\n      const yaml = `name: \"Alice Smith\"\ngreeting: \"Hello, World!\"`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"single quoted strings return valid\", () => {\n      const yaml = `name: 'Alice Smith'\ngreeting: 'Hello, World!'`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"multi-line scalar with literal block (|) returns valid\", () => {\n      const yaml = `description: |\n  This is a multi-line\n  block of text that\n  preserves newlines.`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"multi-line scalar with folded block (>) returns valid\", () => {\n      const yaml = `description: >\n  This is a folded\n  block of text that\n  joins lines.`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"document start marker (---) returns valid\", () => {\n      const yaml = `---\nname: Alice\nage: 30`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"document end marker (...) returns valid\", () => {\n      const yaml = `name: Alice\n...`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"document markers --- and ... together return valid\", () => {\n      const yaml = `---\nname: Alice\n...`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"boolean values return valid\", () => {\n      const yaml = `enabled: true\ndisabled: false`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"null values return valid\", () => {\n      const yaml = `value: null\nother:`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"numeric values return valid\", () => {\n      const yaml = `count: 42\nprice: 19.99\nnegative: -5`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n  });\n\n  describe(\"invalid YAML cases\", () => {\n    test(\"tab indentation returns error with line number\", () => {\n      const yaml = `name: Alice\\n\\tage: 30`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThanOrEqual(1);\n      const tabError = result.errors.find((e) =>\n        e.message.toLowerCase().includes(\"tab\")\n      );\n      expect(tabError).toBeDefined();\n      expect(tabError!.line).toBe(2);\n    });\n\n    test(\"tab indentation includes column number\", () => {\n      const yaml = `name: Alice\\n\\tage: 30`;\n      const result = validateYaml(yaml);\n      const tabError = result.errors.find((e) =>\n        e.message.toLowerCase().includes(\"tab\")\n      );\n      expect(tabError).toBeDefined();\n      expect(tabError!.column).toBeDefined();\n      expect(tabError!.column).toBe(1);\n    });\n\n    test(\"unclosed double quoted string returns error with line number\", () => {\n      const yaml = `name: \"Alice`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThanOrEqual(1);\n      const quoteError = result.errors.find((e) =>\n        e.message.toLowerCase().includes(\"unclosed\")\n      );\n      expect(quoteError).toBeDefined();\n      expect(quoteError!.line).toBe(1);\n    });\n\n    test(\"unclosed single quoted string returns error with line number\", () => {\n      const yaml = `name: 'Alice`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThanOrEqual(1);\n      const quoteError = result.errors.find((e) =>\n        e.message.toLowerCase().includes(\"unclosed\")\n      );\n      expect(quoteError).toBeDefined();\n      expect(quoteError!.line).toBe(1);\n    });\n\n    test(\"unmatched flow collection braces return error with line number\", () => {\n      const yaml = `data: {key: value`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThanOrEqual(1);\n    });\n\n    test(\"unmatched flow collection brackets return error with line number\", () => {\n      const yaml = `[item1, item2`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThanOrEqual(1);\n    });\n  });\n\n  describe(\"edge cases\", () => {\n    test(\"file with only comments returns valid\", () => {\n      const yaml = `# Comment line 1\n# Comment line 2\n# Comment line 3`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"file with only whitespace returns valid\", () => {\n      const result = validateYaml(\"   \\n  \\n   \");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"single scalar value returns valid\", () => {\n      const result = validateYaml(\"hello\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"windows-style line endings are handled\", () => {\n      const yaml = \"name: Alice\\r\\nage: 30\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"block scalar with chomping indicator returns valid\", () => {\n      const yaml = `text: |+\n  line one\n  line two`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"block scalar with strip indicator returns valid\", () => {\n      const yaml = `text: |-\n  line one\n  line two`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"inline comment after value returns valid\", () => {\n      const yaml = `name: Alice # this is a comment`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"sequence entry with nested mapping returns valid\", () => {\n      const yaml = `- name: Alice\n- name: Bob`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"valid flow mapping returns valid\", () => {\n      const yaml = `{name: Alice, age: 30}`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"valid flow sequence returns valid\", () => {\n      const yaml = `[apple, banana, cherry]`;\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n  });\n});\n\ndescribe(\"validateYamlFile\", () => {\n  let tmpDir: string;\n\n  beforeAll(async () => {\n    tmpDir = await mkdtemp(join(tmpdir(), \"yaml-validator-test-\"));\n  });\n\n  afterAll(async () => {\n    await rm(tmpDir, { recursive: true, force: true });\n  });\n\n  test(\"valid file with valid YAML returns valid result\", async () => {\n    const filePath = join(tmpDir, \"valid.yaml\");\n    await Bun.write(filePath, \"name: Alice\\nage: 30\\n\");\n\n    const result = await validateYamlFile(filePath);\n    expect(result.valid).toBe(true);\n    expect(result.errors).toHaveLength(0);\n  });\n\n  test(\"non-existent file returns file-not-found error\", async () => {\n    const filePath = join(tmpDir, \"does-not-exist.yaml\");\n\n    const result = await validateYamlFile(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.errors).toHaveLength(1);\n    expect(result.errors[0].line).toBe(0);\n    expect(result.errors[0].message).toContain(\"File not found\");\n    expect(result.errors[0].message).toContain(\"does-not-exist.yaml\");\n  });\n\n  test(\"valid file with invalid YAML returns errors with details\", async () => {\n    const filePath = join(tmpDir, \"invalid.yaml\");\n    await Bun.write(filePath, 'name: \"Alice\\nage: 30\\n');\n\n    const result = await validateYamlFile(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.errors.length).toBeGreaterThanOrEqual(1);\n    expect(result.errors[0].line).toBeGreaterThan(0);\n    expect(result.errors[0].message.length).toBeGreaterThan(0);\n  });\n});\n\ndescribe(\"formatValidationError\", () => {\n  test(\"formats error with line number and message\", () => {\n    const error: ValidationError = {\n      line: 5,\n      message: \"Tab character found; YAML requires spaces for indentation\",\n    };\n    const formatted = formatValidationError(error);\n    expect(formatted).toBe(\n      \"  Line 5: Tab character found; YAML requires spaces for indentation\"\n    );\n  });\n\n  test(\"formats error with line number, column, and message\", () => {\n    const error: ValidationError = {\n      line: 10,\n      column: 3,\n      message: \"Unclosed quoted string\",\n    };\n    const formatted = formatValidationError(error);\n    expect(formatted).toBe(\n      \"  Line 10, Column 3: Unclosed quoted string\"\n    );\n  });\n});\n"
