input.content:
export interface ValidationError {
  line: number;
  column?: number;
  message: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

export function formatValidationError(error: ValidationError): string {
  if (error.column !== undefined) {
    return `  Line ${error.line}, Column ${error.column}: ${error.message}`;
  }
  return `  Line ${error.line}: ${error.message}`;
}

export function validateYaml(content: string): ValidationResult {
  const errors: ValidationError[] = [];

  if (content.trim() === "") {
    return { valid: true, errors: [] };
  }

  const lines = content.replace(/\r\n/g, "\n").split("\n");
  const indentStack: number[] = [0];
  let inBlockScalar = false;
  let blockScalarIndent = -1;
  let blockScalarLine = -1;

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const line = lines[i];

    if (line.trim() === "") {
      continue;
    }

    if (line.trim() === "---" || line.trim() === "...") {
      inBlockScalar = false;
      blockScalarIndent = -1;
      continue;
    }

    if (inBlockScalar) {
      const currentIndent = getIndent(line);
      if (blockScalarIndent === -1) {
        if (line.trim().startsWith("#")) {
          continue;
        }
        if (currentIndent > getIndent(lines[blockScalarLine])) {
          blockScalarIndent = currentIndent;
          continue;
        } else {
          inBlockScalar = false;
          blockScalarIndent = -1;
        }
      } else {
        if (currentIndent >= blockScalarIndent) {
          continue;
        } else if (line.trim().startsWith("#")) {
          continue;
        } else {
          inBlockScalar = false;
          blockScalarIndent = -1;
        }
      }
    }

    if (line.trim().startsWith("#")) {
      continue;
    }

    const tabMatch = line.match(/\t/);
    if (tabMatch) {
      errors.push({
        line: lineNum,
        column: (tabMatch.index ?? 0) + 1,
        message: "Tab character found; YAML requires spaces for indentation",
      });
      continue;
    }

    const currentIndent = getIndent(line);
    const trimmed = line.trim();

    if (isFlowCollection(trimmed)) {
      const flowError = validateFlowCollection(trimmed);
      if (flowError) {
        errors.push({ line: lineNum, message: flowError });
      }
      continue;
    }

    if (!hasBalancedQuotes(trimmed)) {
      errors.push({
        line: lineNum,
        message: "Unclosed quoted string",
      });
      continue;
    }

    if (isSequenceEntry(trimmed)) {
      if (currentIndent > indentStack[indentStack.length - 1]) {
        indentStack.push(currentIndent);
      } else {
        while (
          indentStack.length > 1 &&
          indentStack[indentStack.length - 1] > currentIndent
        ) {
          indentStack.pop();
        }
      }

      const afterDash = trimmed.slice(1).trim();
      if (afterDash !== "" && isMappingEntry(afterDash)) {
        const blockIndicator = extractBlockScalarIndicator(afterDash);
        if (blockIndicator) {
          inBlockScalar = true;
          blockScalarLine = i;
          blockScalarIndent = -1;
        }
      }
      continue;
    }

    if (isMappingEntry(trimmed)) {
      if (currentIndent > indentStack[indentStack.length - 1]) {
        indentStack.push(currentIndent);
      } else {
        while (
          indentStack.length > 1 &&
          indentStack[indentStack.length - 1] > currentIndent
        ) {
          indentStack.pop();
        }
      }

      const blockIndicator = extractBlockScalarIndicator(trimmed);
      if (blockIndicator) {
        inBlockScalar = true;
        blockScalarLine = i;
        blockScalarIndent = -1;
      }
      continue;
    }

    if (isPlainScalar(trimmed, i, lines.length)) {
      continue;
    }

    errors.push({
      line: lineNum,
      message: "Invalid YAML syntax",
    });
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

export async function validateYamlFile(
  filePath: string
): Promise<ValidationResult> {
  try {
    const file = Bun.file(filePath);
    const exists = await file.exists();
    if (!exists) {
      return {
        valid: false,
        errors: [{ line: 0, message: `File not found: ${filePath}` }],
      };
    }
    const content = await file.text();
    return validateYaml(content);
  } catch (err: unknown) {
    const message =
      err instanceof Error ? err.message : "Unknown error reading file";
    return {
      valid: false,
      errors: [{ line: 0, message: `Error reading file: ${message}` }],
    };
  }
}

function getIndent(line: string): number {
  const match = line.match(/^( *)/);
  return match ? match[1].length : 0;
}

function hasBalancedQuotes(line: string): boolean {
  let inDouble = false;
  let inSingle = false;
  let escaped = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];

    if (escaped) {
      escaped = false;
      continue;
    }

    if (!inDouble && !inSingle) {
      if (ch === "#" && i > 0 && line[i - 1] === " ") {
        return true;
      }
    }

    if (ch === "\\" && inDouble) {
      escaped = true;
      continue;
    }

    if (ch === '"' && !inSingle) {
      inDouble = !inDouble;
    } else if (ch === "'" && !inDouble) {
      if (inSingle && i + 1 < line.length && line[i + 1] === "'") {
        i++;
        continue;
      }
      inSingle = !inSingle;
    }
  }

  return !inDouble && !inSingle;
}

function isMappingEntry(line: string): boolean {
  let inDouble = false;
  let inSingle = false;
  let escaped = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];

    if (escaped) {
      escaped = false;
      continue;
    }

    if (ch === "\\" && inDouble) {
      escaped = true;
      continue;
    }

    if (ch === '"' && !inSingle) {
      inDouble = !inDouble;
    } else if (ch === "'" && !inDouble) {
      if (inSingle && i + 1 < line.length && line[i + 1] === "'") {
        i++;
        continue;
      }
      inSingle = !inSingle;
    }

    if (!inDouble && !inSingle && ch === ":") {
      if (i + 1 === line.length || line[i + 1] === " " || line[i + 1] === "\t") {
        return true;
      }
    }
  }

  return false;
}

function isSequenceEntry(line: string): boolean {
  return line === "-" || line.startsWith("- ");
}

function isBlockScalarIndicator(value: string): boolean {
  const trimmed = value.trim();
  return /^[|>][+-]?\s*(#.*)?$/.test(trimmed);
}

function extractBlockScalarIndicator(line: string): boolean {
  const colonIndex = findUnquotedColon(line);
  if (colonIndex === -1) return false;
  const value = line.slice(colonIndex + 1).trim();
  return isBlockScalarIndicator(value);
}

function findUnquotedColon(line: string): number {
  let inDouble = false;
  let inSingle = false;
  let escaped = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];

    if (escaped) {
      escaped = false;
      continue;
    }

    if (ch === "\\" && inDouble) {
      escaped = true;
      continue;
    }

    if (ch === '"' && !inSingle) {
      inDouble = !inDouble;
    } else if (ch === "'" && !inDouble) {
      if (inSingle && i + 1 < line.length && line[i + 1] === "'") {
        i++;
        continue;
      }
      inSingle = !inSingle;
    }

    if (!inDouble && !inSingle && ch === ":") {
      if (i + 1 === line.length || line[i + 1] === " " || line[i + 1] === "\t") {
        return i;
      }
    }
  }

  return -1;
}

function isFlowCollection(line: string): boolean {
  return (
    (line.startsWith("{") && line.endsWith("}")) ||
    (line.startsWith("[") && line.endsWith("]"))
  );
}

function validateFlowCollection(line: string): string | null {
  let braces = 0;
  let brackets = 0;
  let inDouble = false;
  let inSingle = false;
  let escaped = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];

    if (escaped) {
      escaped = false;
      continue;
    }

    if (ch === "\\" && inDouble) {
      escaped = true;
      continue;
    }

    if (ch === '"' && !inSingle) {
      inDouble = !inDouble;
    } else if (ch === "'" && !inDouble) {
      if (inSingle && i + 1 < line.length && line[i + 1] === "'") {
        i++;
        continue;
      }
      inSingle = !inSingle;
    }

    if (!inDouble && !inSingle) {
      if (ch === "{") braces++;
      else if (ch === "}") braces--;
      else if (ch === "[") brackets++;
      else if (ch === "]") brackets--;

      if (braces < 0) return "Unmatched closing brace '}'";
      if (brackets < 0) return "Unmatched closing bracket ']'";
    }
  }

  if (braces !== 0) return "Unmatched opening brace '{'";
  if (brackets !== 0) return "Unmatched opening bracket '['";
  if (inDouble || inSingle) return "Unclosed quoted string in flow collection";

  return null;
}

function isPlainScalar(
  trimmed: string,
  lineIndex: number,
  totalLines: number
): boolean {
  if (lineIndex === 0 && totalLines === 1) {
    return true;
  }

  if (
    !trimmed.includes(":") &&
    !trimmed.startsWith("- ") &&
    trimmed !== "-" &&
    !trimmed.startsWith("{") &&
    !trimmed.startsWith("[")
  ) {
    return true;
  }

  return false;
}

