/**
 * Main entry point for the rp1 eval test project.
 */

import { greet } from "./utils";
import { validateYamlFile, formatValidationError } from "./yaml-validator";

const command = process.argv[2];

switch (command) {
  case "validate-yaml": {
    const filePath = process.argv[3];
    if (!filePath) {
      console.error(
        `Usage: bun run dev validate-yaml <file-path>

Validates a YAML file for syntactic correctness.

Arguments:
  file-path    Path to the YAML file to validate

Exit codes:
  0    YAML is valid
  1    YAML is invalid or an error occurred`
      );
      process.exit(1);
    }
    const result = await validateYamlFile(filePath);
    if (result.valid) {
      console.log(`${filePath}: Valid YAML`);
      process.exit(0);
    } else {
      const hasIoError = result.errors.some((e) => e.line === 0);
      if (hasIoError) {
        for (const error of result.errors) {
          console.error(`Error: ${error.message}`);
        }
      } else {
        console.error(`${filePath}: Invalid YAML`);
        for (const error of result.errors) {
          console.error(formatValidationError(error));
        }
      }
      process.exit(1);
    }
    break;
  }
  default: {
    const name = command ?? "World";
    console.log(greet(name));
  }
}

