import { validateYaml } from "./validate-yaml";

// Performance test: generate a large YAML file (1000 lines)
function generateLargeYaml(lineCount: number): string {
  const lines: string[] = ["---", "# Large configuration file"];
  for (let i = 0; i < lineCount / 5; i++) {
    lines.push(`service_${i}:`);
    lines.push(`  name: "service-${i}"`);
    lines.push(`  port: ${3000 + i}`);
    lines.push(`  enabled: ${i % 2 === 0}`);
    lines.push(`  tags:`);
    lines.push(`    - tag_${i}_a`);
    lines.push(`    - tag_${i}_b`);
  }
  return lines.join("\n");
}

console.log("=== Performance Test ===");
const largeYaml = generateLargeYaml(1000);
const lineCount = largeYaml.split("\n").length;
console.log(`Generated YAML with ${lineCount} lines`);

const startTime = performance.now();
const iterations = 100;
for (let i = 0; i < iterations; i++) {
  validateYaml(largeYaml);
}
const endTime = performance.now();
const avgTime = (endTime - startTime) / iterations;
console.log(`Average validation time for ${lineCount}-line file: ${avgTime.toFixed(2)}ms`);
console.log(`Total for ${iterations} iterations: ${(endTime - startTime).toFixed(2)}ms`);

// Single run timing
const singleStart = performance.now();
const result = validateYaml(largeYaml);
const singleEnd = performance.now();
console.log(`Single run: ${(singleEnd - singleStart).toFixed(2)}ms, Valid: ${result.valid}`);

// Edge case: very deeply nested YAML
console.log("\n=== Deep Nesting Test ===");
let deepYaml = "";
for (let i = 0; i < 50; i++) {
  deepYaml += " ".repeat(i * 2) + `level${i}:\n`;
}
deepYaml += " ".repeat(100) + "value: deep";
const deepResult = validateYaml(deepYaml);
console.log(`50-level deep nesting: Valid=${deepResult.valid}, Errors=${deepResult.errors.length}`);

// Edge case: YAML with many block scalars
console.log("\n=== Block Scalar Stress Test ===");
let blockYaml = "";
for (let i = 0; i < 100; i++) {
  blockYaml += `field_${i}: |\n  Line 1 of field ${i}\n  Line 2 of field ${i}\n`;
}
const blockResult = validateYaml(blockYaml);
console.log(`100 block scalars: Valid=${blockResult.valid}, Errors=${blockResult.errors.length}`);

// Edge case: Kubernetes-like multi-container pod spec
console.log("\n=== Complex K8s Pod Spec ===");
const k8sYaml = `apiVersion: v1
kind: Pod
metadata:
  name: multi-container-pod
  labels:
    app: multi-container
    environment: production
  annotations:
    description: "A pod with multiple containers"
spec:
  initContainers:
    - name: init-db
      image: busybox:latest
      command:
        - sh
        - -c
        - "until nslookup db; do echo waiting; sleep 2; done"
  containers:
    - name: app
      image: my-app:v2.1.0
      ports:
        - containerPort: 8080
          name: http
          protocol: TCP
        - containerPort: 9090
          name: metrics
      env:
        - name: DATABASE_URL
          valueFrom:
            secretKeyRef:
              name: db-secret
              key: url
        - name: LOG_LEVEL
          value: "info"
      volumeMounts:
        - name: config-vol
          mountPath: /etc/config
          readOnly: true
      resources:
        requests:
          cpu: "250m"
          memory: "256Mi"
        limits:
          cpu: "1"
          memory: "1Gi"
      livenessProbe:
        httpGet:
          path: /healthz
          port: 8080
        initialDelaySeconds: 15
        periodSeconds: 20
      readinessProbe:
        httpGet:
          path: /readyz
          port: 8080
        initialDelaySeconds: 5
        periodSeconds: 10
    - name: sidecar
      image: envoy:latest
      ports:
        - containerPort: 15001
  volumes:
    - name: config-vol
      configMap:
        name: app-config
  restartPolicy: Always
  terminationGracePeriodSeconds: 30`;
const k8sResult = validateYaml(k8sYaml);
console.log(`K8s Pod spec: Valid=${k8sResult.valid}, Errors=${k8sResult.errors.length}`);
if (k8sResult.errors.length > 0) {
  console.log("Errors:", JSON.stringify(k8sResult.errors, null, 2));
}

// Edge case: GitHub Actions with complex multi-line run blocks
console.log("\n=== GitHub Actions Complex ===");
const ghaYaml = `name: Release
on:
  push:
    tags:
      - "v*.*.*"
permissions:
  contents: write
  packages: write
jobs:
  release:
    runs-on: ubuntu-latest
    strategy:
      matrix:
        node-version: [18, 20, 22]
    steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 0
      - name: Setup Node
        uses: actions/setup-node@v4
        with:
          node-version: \${{ matrix.node-version }}
      - run: npm ci
      - run: npm test
