const ghaResult = validateYaml(ghaYaml);
console.log(`GHA workflow: Valid=${ghaResult.valid}, Errors=${ghaResult.errors.length}`);
if (ghaResult.errors.length > 0) {
  console.log("Errors:", JSON.stringify(ghaResult.errors, null, 2));
}

// Test false-positive: ensure valid YAML isn't rejected
console.log("\n=== False Positive Check ===");
const falsePositiveTests = [
  { name: "URL with colon", yaml: 'url: "https://example.com:8080"' },
  { name: "Time value", yaml: "time: 12:30:00" },
  { name: "Colon in value", yaml: 'msg: "Error: something failed"' },
  { name: "Multiline with special chars", yaml: "script: |\n  echo 'hello'\n  echo \"world\"" },
  { name: "List with inline map", yaml: "items:\n  - {name: a, value: 1}\n  - {name: b, value: 2}" },
  { name: "Empty mapping value", yaml: "config:\n  sub:\n    key:" },
  { name: "Hyphenated key", yaml: "my-key: my-value" },
  { name: "Underscore key", yaml: "my_key: my_value" },
  { name: "Numeric key-like", yaml: "123: numeric key" },
  { name: "Boolean values", yaml: "a: true\nb: false\nc: yes\nd: no\ne: on\nf: off" },
];

let fpPass = 0;
let fpFail = 0;
for (const t of falsePositiveTests) {
  const r = validateYaml(t.yaml);
  if (r.valid) {
    fpPass++;
  } else {
    fpFail++;
    console.log(`  FALSE POSITIVE: "${t.name}" rejected: ${JSON.stringify(r.errors)}`);
  }
}
console.log(`False positive check: ${fpPass}/${falsePositiveTests.length} passed`);

// Test false-negative: ensure invalid YAML is rejected
console.log("\n=== False Negative Check ===");
const falseNegativeTests = [
  { name: "Tab indent", yaml: "key:\n\tvalue: 1" },
  { name: "Unclosed double quote", yaml: 'key: "unclosed' },
  { name: "Unclosed single quote", yaml: "key: 'unclosed" },
  { name: "Unbalanced brace", yaml: "key: {a: 1, b: 2" },
  { name: "Unbalanced bracket", yaml: "key: [1, 2, 3" },
];

let fnPass = 0;
let fnFail = 0;
for (const t of falseNegativeTests) {
  const r = validateYaml(t.yaml);
  if (!r.valid) {
    fnPass++;
  } else {
    fnFail++;
    console.log(`  FALSE NEGATIVE: "${t.name}" accepted but should be rejected`);
  }
}
console.log(`False negative check: ${fnPass}/${falseNegativeTests.length} passed`);

console.log("\n=== OVERALL RESULTS ===");
console.log(`Performance: ${avgTime.toFixed(2)}ms avg for ${lineCount}-line file (target: <1000ms)`);
